mapper.select:
SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM customers c
         JOIN users u ON u.user_id = c.user_id
WHERE c.customer_id = #{customerId}
  AND u.center_id   = #{centerId}
LIMIT 1

SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM customers c
WHERE c.customer_id = #{customerId}
  AND c.user_id     = #{userId}
LIMIT 1

mapper.update:
UPDATE memo_chats
SET content    = #{content},
    updated_at = NOW(),
    updated_by = #{updatedBy}
WHERE chat_id = #{chatId}
  AND is_deleted = 0
